const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define JFK Airport location
  const jfk = ee.Geometry.Point([-73.7781, 40.6413]);

  // 2. Get temperature on June 24, 2025
  const date2025 = '2025-06-24';
  const col2025 = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .filterDate(date2025, '2025-06-25')
    .filterBounds(jfk)
    .select('temperature_2m');

  const size2025 = col2025.size().getInfo();
  console.log(`June 24, 2025 images: ${size2025}`);

  if (size2025 === 0) {
    console.log("No data for June 24, 2025");
    console.log("<answer>C1</answer>");
    return;
  }

  // Get mean temperature for June 24, 2025 (convert from Kelvin to Celsius)
  const temp2025K = col2025.mean().reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: jfk,
    scale: 11132,
    maxPixels: 1e9
  }).get('temperature_2m').getInfo();

  if (temp2025K === null || temp2025K === undefined) {
    console.log("Failed to get 2025 temperature");
    console.log("<answer>C3</answer>");
    return;
  }

  const temp2025 = temp2025K - 273.15;
  console.log(`June 24, 2025 temp: ${temp2025.toFixed(2)}°C`);

  // Validate temperature range
  if (temp2025 < -50 || temp2025 > 60) {
    console.log("Invalid temperature range for 2025");
    console.log("<answer>C3</answer>");
    return;
  }

  // 3. Get historical June temperatures (2020-2024)
  const historicalYears = [2020, 2021, 2022, 2023, 2024];
  let maxHistoricalTemp = -999;

  for (let year of historicalYears) {
    const startDate = `${year}-06-01`;
    const endDate = `${year}-07-01`;

    const colYear = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
      .filterDate(startDate, endDate)
      .filterBounds(jfk)
      .select('temperature_2m');

    const sizeYear = colYear.size().getInfo();

    if (sizeYear === 0) {
      console.log(`No data for June ${year}`);
      console.log("<answer>C1</answer>");
      return;
    }

    // Get max temperature for this June
    const maxTempK = colYear.max().reduceRegion({
      reducer: ee.Reducer.max(),
      geometry: jfk,
      scale: 11132,
      maxPixels: 1e9
    }).get('temperature_2m').getInfo();

    if (maxTempK === null || maxTempK === undefined) {
      console.log(`Failed to get ${year} temperature`);
      console.log("<answer>C3</answer>");
      return;
    }

    const maxTemp = maxTempK - 273.15;
    console.log(`June ${year} max: ${maxTemp.toFixed(2)}°C (${sizeYear} imgs)`);

    if (maxTemp > maxHistoricalTemp) {
      maxHistoricalTemp = maxTemp;
    }
  }

  console.log(`Historical max (2020-2024): ${maxHistoricalTemp.toFixed(2)}°C`);

  // 4. Compare and determine answer
  if (temp2025 > maxHistoricalTemp) {
    console.log("June 24, 2025 was hotter than any day in June 2020-2024");
    console.log("<answer>A</answer>");
  } else {
    console.log("June 24, 2025 was NOT hotter than historical maximum");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
